import re
import os

OUT = "/workspace/src/data/juniorWords.ts"


def make_id(english: str) -> str:
    """Create a valid JS identifier suffix from the English word/phrase."""
    s = english.lower().strip()
    s = re.sub(r"['’.]", "", s)
    s = re.sub(r"[^a-z0-9]+", "_", s)
    s = s.strip("_")
    if s[0].isdigit():
        s = "_" + s
    return s


def esc(s: str) -> str:
    """Escape single quotes for the TypeScript string."""
    return s.replace("'", "\\'")


def word(en: str, zh: str, phonetic: str, example: str):
    return {
        "english": en,
        "chinese": zh,
        "phonetic": phonetic,
        "example": example,
    }


